function quietSpans(minuteMarks, horizon) {
  const result = [];
  let prev = 0;
  for (const mark of minuteMarks) {
    if (mark >= horizon) break;
    if (prev < mark) result.push([prev, mark]);
    prev = Math.max(prev, mark + 1);
  }
  if (prev < horizon) result.push([prev, horizon]);
  return result;
}
