function foldParcel(s) {
  let stack = [];
  let result = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '\\') {
      if (i + 1 < s.length) {
        result.push(s[i + 1]);
        i += 2;
      } else {
        return null;
      }
    } else if (s[i] === '(') {
      stack.push(result);
      result = [];
      i++;
    } else if (s[i] === ')') {
      if (stack.length === 0) return null;
      result = stack.pop().concat(result.reverse());
      i++;
    } else {
      result.push(s[i]);
      i++;
    }
  }
  if (stack.length > 0) return null;
  return result.join('');
}
