function patchRows(base, patch) {
  const map = new Map(base.map(row => [row.id, row]));
  for (const p of patch) {
    if (p.remove) {
      map.delete(p.id);
    } else {
      map.set(p.id, { ...map.get(p.id), ...p });
    }
  }
  return Array.from(map.values());
}
