function roundTag(s, p) {
  let [intPart, fracPart] = s.split('.');
  intPart = intPart.replace(/^0+/, '') || '0';
  fracPart = fracPart.slice(0, p + 1);
  let num = parseFloat(intPart + '.' + fracPart);
  let rounded = Math.round(num * Math.pow(10, p)) / Math.pow(10, p);
  let result = rounded.toFixed(p).replace(/\.?0+$/, '');
  return result === '-0' ? '0' : result;
}
