function alternatingBins(...nums) {
  if (nums.length === 0) return [];
  const bins = [];
  let currentBin = [nums[0]];
  let lastNonZeroSign = Math.sign(nums[0]);

  for (let i = 1; i < nums.length; i++) {
    const num = nums[i];
    if (num === 0) {
      currentBin.push(num);
      continue;
    }
    const currentSign = Math.sign(num);
    if (currentSign !== lastNonZeroSign) {
      currentBin.push(num);
      lastNonZeroSign = currentSign;
    } else {
      bins.push(currentBin);
      currentBin = [num];
      lastNonZeroSign = currentSign;
    }
  }
  bins.push(currentBin);
  return bins;
}
