function weightedSeat(weights, seats) {
  if (weights.length === 0) return [];
  const total = weights.reduce((a, b) => a + b, 0);
  const allocations = weights.map(w => Math.floor(seats * w / total));
  const remaining = seats - allocations.reduce((a, b) => a + b, 0);
  const fractional = weights.map((w, i) => ({ i, rem: (seats * w / total) % 1 }));
  fractional.sort((a, b) => b.rem - a.rem || a.i - b.i);
  for (let i = 0; i < remaining; i++) {
    allocations[fractional[i].i]++;
  }
  return allocations;
}
