function noteLinks(edges, start) {
  const graph = {};
  for (const [from, to] of edges) {
    if (!graph[from]) graph[from] = new Set();
    graph[from].add(to);
  }

  const visited = new Set();
  const result = [];
  let current = start;

  while (current && !visited.has(current)) {
    visited.add(current);
    result.push(current);
    const neighbors = graph[current];
    if (neighbors && neighbors.size === 1) {
      current = [...neighbors][0];
    } else {
      break;
    }
  }

  return result;
}
