function escapedPairs(s) {
  if (s === '') return [];
  let pairs = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '\\') {
      if (i + 1 >= s.length) return null;
      i += 2;
    } else if (s[i] === ',') {
      i++;
    } else {
      let key = '';
      let value = '';
      let eqFound = false;
      while (i < s.length) {
        if (s[i] === '\\') {
          if (i + 1 >= s.length) return null;
          key += s[i + 1];
          i += 2;
        } else if (s[i] === '=' && !eqFound) {
          eqFound = true;
          i++;
        } else if (s[i] === ',' && !eqFound) {
          break;
        } else {
          if (eqFound) value += s[i];
          else key += s[i];
          i++;
        }
      }
      if (!eqFound) return null;
      pairs.push([key, value]);
    }
  }
  return pairs;
}
