function peakShelves(arr) {
  const result = [];
  for (let i = 0; i < arr.length; ) {
    let j = i;
    while (j < arr.length && arr[j] === arr[i]) j++;
    const left = i > 0 ? arr[i - 1] : -Infinity;
    const right = j < arr.length ? arr[j] : -Infinity;
    if (arr[i] > left && arr[i] > right) {
      result.push([i, j, arr[i]]);
    }
    i = j;
  }
  return result;
}
