function serialNext(s) {
  const match = s.match(/^([a-z]*)(\d+)$/);
  if (!match) return null;
  const [_, prefix, numStr] = match;
  const num = parseInt(numStr, 10) + 1;
  const newNumStr = num.toString();
  return prefix + newNumStr.padStart(numStr.length, '0');
}
