function nestDepths(s) {
  let depth = 0, maxDepth = 0, inQuote = false, escape = false;
  for (let c of s) {
    if (escape) {
      if (c === '\\' || c === "'") escape = false;
      else escape = false;
    } else if (c === "'") inQuote = !inQuote;
    else if (c === '[' && !inQuote) {
      depth++;
      maxDepth = Math.max(maxDepth, depth);
    } else if (c === ']' && !inQuote) {
      depth--;
      if (depth < 0) return null;
    } else if (c === '\\' && !inQuote) escape = true;
  }
  if (inQuote || escape) return null;
  return maxDepth;
}
