function windowVotes(strings, windowSize) {
  const result = [];
  for (let i = 0; i <= strings.length - windowSize; i++) {
    const window = strings.slice(i, i + windowSize);
    const freq = {};
    let maxFreq = 0, latestStr = '';
    for (const str of window) {
      freq[str] = (freq[str] || 0) + 1;
      if (freq[str] >= maxFreq) {
        maxFreq = freq[str];
        latestStr = str;
      }
    }
    result.push(latestStr);
  }
  return result;
}
