function rangeBadges(nums) {
  if (nums.length === 0) return "";
  let result = [];
  let start = nums[0], end = nums[0];
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] === end + 1) end = nums[i];
    else {
      if (end - start + 1 >= 3) result.push(`${start}..${end}`);
      else for (let j = start; j <= end; j++) result.push(j.toString());
      start = nums[i];
      end = nums[i];
    }
  }
  if (end - start + 1 >= 3) result.push(`${start}..${end}`);
  else for (let j = start; j <= end; j++) result.push(j.toString());
  return result.join(",");
}
