function orderCrates(labels, dependencies) {
    const graph = {};
    const inDegree = {};
    const labelSet = new Set(labels);

    for (const label of labels) {
        graph[label] = [];
        inDegree[label] = 0;
    }

    for (const [before, after] of dependencies) {
        if (labelSet.has(before) && labelSet.has(after) && !graph[before].includes(after)) {
            graph[before].push(after);
            inDegree[after]++;
        }
    }

    const queue = [];
    for (const label of labels) {
        if (inDegree[label] === 0) queue.push(label);
    }

    const result = [];
    while (queue.length > 0) {
        queue.sort();
        const current = queue.shift();
        result.push(current);
        for (const neighbor of graph[current]) {
            inDegree[neighbor]--;
            if (inDegree[neighbor] === 0) queue.push(neighbor);
        }
    }

    return result.length === labels.length ? result : null;
}
