function softWrap(words, width) {
  if (words.length === 0) return [];
  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    if (word.length > width) {
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }
      lines.push(word);
    } else {
      const newLength = currentLength + (currentLine.length > 0 ? 1 + word.length : word.length);
      if (newLength > width) {
        lines.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      } else {
        currentLine.push(word);
        currentLength = newLength;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}
