function mergeDots(a, b) {
  const x = a.split('.').map(Number);
  const y = b.split('.').map(Number);
  const max = Math.max(x.length, y.length);
  for (let i = 0; i < max; i++) {
    const xi = i < x.length ? x[i] : 0;
    const yi = i < y.length ? y[i] : 0;
    if (xi < yi) return -1;
    if (xi > yi) return 1;
  }
  return 0;
}
