function digitBudget(budget, costs) {
  const purchasedIndices = [];
  for (let i = 0; i < costs.length; i++) {
    if (costs[i] <= budget) {
      purchasedIndices.push(i);
      budget -= costs[i];
    }
  }
  return [purchasedIndices, budget];
}
