function holeFill(arr) {
  const result = [...arr];
  const n = arr.length;
  for (let i = 0; i < n; i++) {
    if (result[i] === null) {
      let left = null;
      let right = null;
      for (let j = i - 1; j >= 0; j--) {
        if (result[j] !== null) {
          left = result[j];
          break;
        }
      }
      for (let j = i + 1; j < n; j++) {
        if (result[j] !== null) {
          right = result[j];
          break;
        }
      }
      if (left !== null && right !== null) {
        result[i] = left;
      } else if (left !== null) {
        result[i] = left;
      } else if (right !== null) {
        result[i] = right;
      }
    }
  }
  return result;
}
