function bracketTotals(s) {
  let i = 0;
  function parse() {
    let sum = 0;
    let depth = 1;
    while (i < s.length) {
      let c = s[i];
      if (c === ' ') { i++; continue; }
      if (c === ',') { i++; return sum; }
      if (c === '[') {
        i++;
        const sub = parse();
        if (sub === null) return null;
        sum += sub * depth;
        if (s[i] !== ']') return null;
        i++;
        continue;
      }
      if (c === ']') { i++; return sum; }
      let num = 0;
      let sign = 1;
      if (c === '-') { sign = -1; i++; c = s[i]; }
      if (!/^\d$/.test(c)) return null;
      while (i < s.length && /^\d$/.test(s[i])) {
        num = num * 10 + parseInt(s[i], 10);
        i++;
      }
      sum += num * sign * depth;
    }
    return sum;
  }
  const result = parse();
  if (i !== s.length || result === null) return null;
  return result;
}
