function runInventory(s, replacements) {
  for (const [c, count] of replacements) {
    let i = 0;
    while (i < s.length) {
      if (s[i] === c) {
        let j = i;
        while (j < s.length && s[j] === c) j++;
        const runLength = j - i;
        if (count === 0) {
          s = s.slice(0, i) + s.slice(j);
        } else {
          s = s.slice(0, i) + c.repeat(count) + s.slice(j);
        }
        i += count;
      } else {
        i++;
      }
    }
  }
  return s;
}
