function batchCredits(events, lifetime) {
  const timeMap = new Map();
  const result = [];

  for (const [time, amount] of events) {
    if (!timeMap.has(time)) timeMap.set(time, []);
    timeMap.get(time).push(amount);
  }

  const times = Array.from(timeMap.keys()).sort((a, b) => a - b);

  for (const time of times) {
    const amounts = timeMap.get(time);
    const expireTime = time - lifetime;
    for (const [t, credits] of timeMap.entries()) {
      if (t < expireTime) {
        for (const credit of credits) {
          if (credit < 0) continue;
          const idx = result.findIndex(r => r[0] === t);
          if (idx !== -1) result[idx][1] -= credit;
          else result.push([t, -credit]);
        }
        timeMap.delete(t);
      }
    }
    let totalLive = 0;
    for (const amount of amounts) {
      totalLive += amount;
    }
    result.push([time, totalLive]);
  }

  return result;
}
